# ==============================================================================# 054_EVENT_DISPATCHER.py# ==============================================================================import sqlite3from pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")# ==============================================================================# DISPATCH TABLE# ==============================================================================cur.execute("""CREATE TABLE IF NOT EXISTS event_dispatch(    id INTEGER PRIMARY KEY AUTOINCREMENT,    dispatched_at TEXT,    origin TEXT,    event_name TEXT,    destination TEXT,    action TEXT,    status TEXT)""")conn.commit()# ==============================================================================# EVENTOS AINDA NÃƒO DESPACHADOS# ==============================================================================cur.execute("""SELECTid,origin,event_name,actionFROM event_historyWHERE id NOT IN (    SELECT DISTINCT id    FROM event_dispatch)ORDER BY id""")events = cur.fetchall()print("="*80)print("EVENT DISPATCHER")print("="*80)total = 0for event in events:    destination = "MAESTRO"    if event["action"] == "DISPATCH_CRITICAL":        destination = "RESOURCE_MANAGER"    elif event["action"] == "SYSTEM_AVAILABLE":        destination = "MASTER_CONTROL"    cur.execute("""    INSERT INTO event_dispatch(        dispatched_at,        origin,        event_name,        destination,        action,        status    )    VALUES(?,?,?,?,?,?)    """,(        datetime.now().isoformat(),        event["origin"],        event["event_name"],        destination,        event["action"],        "DISPATCHED"    ))    total += 1    print(        f"{event['event_name']:<32}"        f"{destination:<22}"        f"DISPATCHED"    )conn.commit()print("="*80)cur.execute("""SELECT COUNT(*)FROM event_dispatch""")print("EVENTOS DESPACHADOS :", cur.fetchone()[0])print("="*80)conn.close()

